<?php require __DIR__.'/../bootstrap/app.php';$db=Database::get();$slug=(string)($_GET['slug']??'');
if($slug!==''){$s=$db->prepare("SELECT title,body,created_at FROM blog_posts WHERE slug=? AND is_published=1");$s->execute([$slug]);$p=$s->fetch();if(!$p)http_response_code(404);$title=$p['title']??'Not found';require __DIR__.'/../app/Views/header.php';?>
<section class="section"><div class="container"><?php if($p):?><h1><?=e($p['title'])?></h1><p><small><?=e($p['created_at'])?></small></p><div><?=nl2br(e($p['body']))?></div><?php else:?><h1>Post not found</h1><?php endif;?><p class="mt-4"><a href="<?=e(url('blog.php'))?>">← All posts</a></p></div></section><?php require __DIR__.'/../app/Views/footer.php';exit;}
$rows=$db->query("SELECT title,slug,excerpt,created_at FROM blog_posts WHERE is_published=1 ORDER BY id DESC")->fetchAll();$title='Blog / News';require __DIR__.'/../app/Views/header.php';?>
<section class="section"><div class="container"><h1>Blog / News</h1><?php if(!$rows):?><p>No posts yet.</p><?php endif;?><?php foreach($rows as $r):?><div class="cardx mb-3"><h3><a href="<?=e(url('blog.php?slug='.$r['slug']))?>"><?=e($r['title'])?></a></h3><small><?=e($r['created_at'])?></small><p><?=e($r['excerpt'])?></p></div><?php endforeach;?></div></section><?php require __DIR__.'/../app/Views/footer.php';?>
